-- Rifts World Book 14: New West - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 18 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~104-new-west-inline-npcs.sql
--
-- Written by scripts/bestiary-sql.mjs from 2 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.


-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 18 notable NPCs are in' AS assertion, count(*) AS got, 18 AS want
  FROM notable_npcs WHERE slug IN ('buck-willis', 'dirk-blane', 'willy-sly', 'ricky-the-dragon-frralla', 'randolf-mccoy', 'winston-h-baltone', 'carlene-baltone', 'joseph-midgard', 'salvador-mendoza', 'arial-spelltwist', 'nathanial-zane', 'lord-lamphrey', 'byaltur', 'weasel-wallace', 'trader-bob', 'kate-the-knife-kelly', 'tc-brennon', 'gene-quartermane');
SELECT 'and the notables 0' AS assertion, count(*) AS got, 0 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('buck-willis', 'dirk-blane', 'willy-sly', 'ricky-the-dragon-frralla', 'randolf-mccoy', 'winston-h-baltone', 'carlene-baltone', 'joseph-midgard', 'salvador-mendoza', 'arial-spelltwist', 'nathanial-zane', 'lord-lamphrey', 'byaltur', 'weasel-wallace', 'trader-bob', 'kate-the-knife-kelly', 'tc-brennon', 'gene-quartermane');

