INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('buck-willis', 'Buck Willis', NULL, 'Bartender and owner of the Trail''s End Saloon, Silvereno', 'rifts', 'Human', 'Wilderness Scout', 10, 'Unprincipled', '53 years old', '6 feet (1.8 m)', NULL, '{"IQ":10,"ME":11,"MA":15,"PS":17,"PP":14,"PE":18,"PB":12,"Spd":13}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bionic right arm (P.S. 20 with the arm) with laser finger and a pair of retractable Vibro-Sabers.', 'A single CFT 86er and a Neuro-Mace, both kept behind the bar.', NULL, 'Gruff, plain-spoken and boastful, yet charming and popular in town; kind toward attractive women, mothers, kids and Dog Boys, and always ready with a yarn or the local gossip.', NULL, NULL, 'Known around Silvereno simply as Buck. A weathered former scout and part-time prospector who has run the Trail''s End for a decade, growing it three times. His claimed past, true or not, takes in scouting for the Coalition Army, riding beside the Cyber-Knight Sir Richard Vandaveer, killing the bandit Black Marvin, time in Tolkeen, fighting Xiticix and riding with the Saber Warriors of the Pecos Empire.', 'Rifts World Book 14: New West p.53'),
('dirk-blane', 'Dirk Blane', NULL, NULL, 'rifts', NULL, 'Gunslinger', 8, 'Anarchist or evil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Said to be retired. One of the most notorious regulars of the Silver Dollar Saloon in Silvereno, a circle rumoured to be tied to the Black Market and to smuggling, whose members hope to found a criminal underground in the growing town. The book gives the whole circle one alignment range rather than one each.', 'Rifts World Book 14: New West p.54'),
('willy-sly', 'Willy Sly', NULL, NULL, 'rifts', NULL, 'Wired-Gunslinger', 3, 'Diabolic', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Quick to anger, and he likes to kill.', NULL, NULL, 'A young gunman among the notorious Silver Dollar Saloon regulars in Silvereno, the circle rumoured to deal with the Black Market and to smuggle.', 'Rifts World Book 14: New West p.54'),
('ricky-the-dragon-frralla', '"Ricky the Dragon" Frralla', NULL, NULL, 'rifts', 'Simvan', 'Simvan warrior', 6, 'Anarchist or evil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Third of the notorious Silver Dollar Saloon regulars in Silvereno, a circle rumoured to be tied to the Black Market and smuggling. The book gives the whole circle one alignment range rather than one each.', 'Rifts World Book 14: New West p.54'),
('randolf-mccoy', 'Randolf McCoy', NULL, 'Owner of a large general store in Silvereno', 'rifts', NULL, 'Smuggler and fence', 7, 'Anarchist or evil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Passes for a respectable Silvereno shopkeeper; in truth a smuggler and fence, and one of the Silver Dollar Saloon circle that hopes to build a criminal underground in town. The book gives the whole circle one alignment range rather than one each.', 'Rifts World Book 14: New West p.54'),
('winston-h-baltone', 'Winston H. Baltone', NULL, 'Partner in one of Silvereno''s silver mines', 'rifts', NULL, 'Forger', 8, 'Anarchist or evil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Carlene Baltone (wife).', NULL, 'A rich mine partner who passes for a respectable businessman and has ambitions in politics; in truth a forger and one of the Silver Dollar Saloon circle. The book gives the whole circle one alignment range rather than one each.', 'Rifts World Book 14: New West p.54'),
('carlene-baltone', 'Carlene Baltone', NULL, NULL, 'rifts', NULL, 'Ley Line Walker', 6, 'Anarchist or evil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Winston H. Baltone (husband).', NULL, 'Wife of the mine partner Winston H. Baltone and, like him, one of the Silver Dollar Saloon circle in Silvereno. The book gives the whole circle one alignment range rather than one each.', 'Rifts World Book 14: New West p.54'),
('joseph-midgard', 'Baron Joseph Midgard', NULL, 'Baron of Hope, Colorado Baronies', 'rifts', NULL, 'Mystic', 14, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Scholarly; convinced people must study the past to avoid reliving it.', NULL, NULL, 'Present ruler of Hope, largest of the Colorado Baronies. He holds every power of decision, aided by a Cabinet of Advisors that is half his own appointees and half elected. He has taken up much of the Golden Ones'' thinking, pushed schooling reforms across the Barony, and means to keep charting the continent.', 'Rifts World Book 14: New West p.58'),
('salvador-mendoza', 'Baron Salvador Mendoza', NULL, 'Baron of Testament, Colorado Baronies', 'rifts', NULL, 'Mind Melter', 6, 'Scrupulous', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Stern and unbending where justice is concerned.', NULL, NULL, 'Leader of Testament, the cattle-country barony that was the second to rise with Hope''s help and that copies Hope''s government and laws.', 'Rifts World Book 14: New West p.60'),
('arial-spelltwist', 'Baroness Arial Spelltwist', NULL, 'Baroness of Wilmington, Colorado Baronies', 'rifts', NULL, 'Mystic', 9, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Playful and a little impulsive; she uses magic for amusement as readily as for anything else, and makes a point of turning up at festivals and meetings and welcoming newcomers.', NULL, NULL, 'An able ruler, skilled at diplomacy and at bargaining over trade, and adored in the city. Outlying towns and farms worry that her welcome of outsiders and her taste for parties could lead Wilmington the way of Charity, though no harm has come of it yet.', 'Rifts World Book 14: New West p.60'),
('nathanial-zane', 'Baron Nathanial Zane', NULL, 'Baron of Charity, Colorado Baronies', 'rifts', NULL, 'Ley Line Walker', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":17,"ME":15,"MA":23,"PE":21}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Greedy for money and power.', 'Lord Lamphrey (his right-hand man); a hand-picked High Council of the Barony''s most powerful and corrupt men.', NULL, 'Ruler of the lawless Barony of Charity. He skims 10% from every business in the city, lawful or not, and 20% from Bandito Arms and Black Market operations, and owns the Golden Eagles casino, a Techno-Wizard arms store and 3 saloons. He and his council may skip a trial and hand down sentences themselves, up to execution on the spot.', 'Rifts World Book 14: New West p.62'),
('lord-lamphrey', 'Lord Lamphrey', NULL, 'Right-hand man of Baron Zane of Charity', 'rifts', 'Elf', 'Gunslinger', 10, 'Miscreant', NULL, NULL, NULL, '{"IQ":15,"PP":26}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Baron Nathanial Zane.', NULL, 'An aged-looking elf and former assassin, by reputation the quickest gun in the West.', 'Rifts World Book 14: New West p.62'),
('byaltur', 'Byaltur', NULL, 'Security Chief of Roderick Warrington III''s carnival', 'rifts', NULL, 'Bounty Hunter (retired)', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":12,"PS":23,"PP":19}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Roderick Warrington III (employer); "Weasel" Wallace (his second in command).', NULL, 'One of the notable henchmen of the carnival owner Roderick Warrington III, heading the carnival''s guards.', 'Rifts World Book 14: New West p.70'),
('weasel-wallace', '"Weasel" Wallace', NULL, 'Second in command of security at Roderick Warrington III''s carnival', 'rifts', NULL, 'Professional thief and master pickpocket', 8, 'Miscreant', NULL, NULL, NULL, '{"PP":21}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Roderick Warrington III (employer); Byaltur (his chief).', NULL, 'One of the notable henchmen of the carnival owner Roderick Warrington III, deputy to the Security Chief.', 'Rifts World Book 14: New West p.70'),
('trader-bob', 'Trader Bob', NULL, 'Head of the concession stands at Roderick Warrington III''s carnival', 'rifts', NULL, 'Smuggler', 7, 'Aberrant', NULL, NULL, NULL, '{"IQ":15,"PP":14}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Roderick Warrington III (employer).', NULL, 'One of the notable henchmen of the carnival owner Roderick Warrington III; he runs the concessions.', 'Rifts World Book 14: New West p.70'),
('kate-the-knife-kelly', 'Kate "The Knife" Kelly', NULL, 'Performer and knife thrower at Roderick Warrington III''s carnival', 'rifts', NULL, 'Gunslinger', 6, 'Anarchist', NULL, NULL, NULL, '{"IQ":12,"PS":20,"PP":22,"PB":14}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Roderick Warrington III (employer and boyfriend).', NULL, 'A carnival knife act and the owner''s present girlfriend. Her Gunslinger specialties, the fast draw, trick shooting and aimed shots, are done with two blades in place of pistols.', 'Rifts World Book 14: New West p.70'),
('tc-brennon', 'T.C. Brennon', NULL, 'Owner of the Shaft Saloon in Silvereno', 'rifts', NULL, 'Mining ''Borg (full conversion)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Full conversion Mining Cyborg body. The drill on the right arm has been swapped for a standard mechanical bionic arm and hand. Chemical sprayer in the chest, kept loaded with knockout gas.', 'A fake heavy plasma grenade kept behind the bar.', NULL, 'Goes easy on miners and avoids doing real harm when he breaks up trouble.', NULL, NULL, 'Among the earliest Silvereno miners to take the Mining-Cyborg conversion. He spent 16 years in the mines, putting his pay aside for the saloon and for schooling his son and daughter in Lazlo, and has run the Shaft for 4 years. His knockout gas does little against many ''Borgs and Juicers; he once ended a brawl between two Mining ''Borgs that nearly wrecked the place by brandishing the grenade, which is a dud. The book prints no level, alignment or attributes for him.', 'Rifts World Book 14: New West p.54'),
('gene-quartermane', 'Gene Quartermane', NULL, 'World traveler and wealthy gambler', 'rifts', NULL, NULL, NULL, 'Anarchist or evil', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Passes for a rich, well-travelled gambler and respectable Silvereno businessman; in truth the Black Market''s liaison within the Silver Dollar Saloon circle that hopes to build a criminal underground in town. The book prints no level or O.C.C. for him, and gives the whole circle one alignment range rather than one each.', 'Rifts World Book 14: New West p.54');
